<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {erpText,erpValue} from '../../erp-language'
import {call} from '../../api'
import {cleanDocument,erpStatus} from '../../erp-form.js'
import ErpForm from './ErpForm.vue'
import ErpApproval from './ErpApproval.vue'
import ErpConnections from './ErpConnections.vue'
import SigningPanel from '../SigningPanel.vue'
import {Button} from '../ui/button'
import {DropdownMenu,DropdownMenuTrigger,DropdownMenuContent,DropdownMenuItem} from '../ui/dropdown-menu'
import {useWorkspaceConfirm} from '../../use-workspace-confirm'
import WorkspaceConfirm from '../WorkspaceConfirm.vue'
const props=defineProps({doctype:{type:String,required:true},name:String,company:String,warehouse:String,initialDocument:Object})
const emit=defineEmits(['open-document','open-list','open-report','quick-create','mapped','saved','error','title'])
const schema=ref(null),data=ref(null),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),form=ref(null),snapshot=ref(''),approval=ref(null),detailsBusy=ref(0)
const confirm=useWorkspaceConfirm(),confirmOpen=confirm.open,confirmTitle=confirm.title,confirmMessage=confirm.message
let editRevision=0,version=0,key=crypto.randomUUID(),previewTimer,rowVersions=new WeakMap()
const api=(method,args={},write=false)=>call('lotus_farm.erp_workbench.'+method,args,write)
const doc=computed(()=>data.value?.doc)
const isNew=computed(()=>!!data.value?.is_new)
const dirty=computed(()=>!!doc.value&&JSON.stringify(cleanDocument(doc.value))!==snapshot.value)
const readonly=computed(()=>!isNew.value&&!data.value?.permissions?.write||Number(doc.value?.docstatus)===2)
const gated=computed(()=>props.doctype==='Purchase Order'||props.doctype==='Material Request'&&doc.value?.material_request_type==='Purchase'||approval.value?.gate||props.doctype==='Payment Entry'&&(doc.value?.payment_type!=='Receive'||doc.value?.party_type==='Supplier')||props.doctype==='Journal Entry'&&['Salary','Advance','Statutory','PurchaseFunding','PurchaseReimbursement'].includes(doc.value?.lotus_payment_kind))
const printUrl=computed(()=>doc.value?'/api/method/lotus_farm.erp_workbench.print_document?'+new URLSearchParams({doctype:props.doctype,name:doc.value.name}):'')
const formSchema=computed(()=>{if(data.value?.editable!=='prices')return schema.value;return {...schema.value,fields:schema.value.fields.map(f=>({...f,read_only:f.fieldtype==='Table'?f.read_only:1})),tables:Object.fromEntries(Object.entries(schema.value.tables).map(([key,t])=>[key,{...t,fields:t.fields.map(f=>({...f,read_only:['rate','lotus_supplier_hint','lotus_notes'].includes(f.fieldname)?f.read_only:1}))}]))}})
const currency=computed(()=>doc.value?.currency||doc.value?.company_currency||'')
const totals=computed(()=>['total_qty','total','net_total','total_taxes_and_charges','grand_total','rounded_total','outstanding_amount'].filter(f=>doc.value?.[f]!=null&&schema.value?.fields?.some(x=>x.fieldname===f)).map(f=>({label:erpText(schema.value.fields.find(x=>x.fieldname===f)?.label||f),value:Number(doc.value[f]||0).toLocaleString('vi-VN',{maximumFractionDigits:2})+(f==='total_qty'?'':currency.value?' '+currency.value:'')})))
async function load(){const id=++version;loading.value=true;error.value='';approval.value=null;try{const s=await api('schema',{doctype:props.doctype});const d=props.initialDocument?{doc:JSON.parse(JSON.stringify(props.initialDocument.doc||props.initialDocument)),permissions:s.permissions,is_new:true,transitions:[],actions:[]}:await api('document',{doctype:props.doctype,name:props.name||undefined,company:props.company,warehouse:props.warehouse});if(id!==version)return;schema.value=s;data.value=d;snapshot.value=props.initialDocument?'':JSON.stringify(cleanDocument(d.doc));key=crypto.randomUUID();emit('title',d.is_new?'Thêm '+erpText(s.title):d.doc.name)}catch(e){if(id===version)error.value=e.message}finally{if(id===version)loading.value=false}}
function beforeUnload(e){if(dirty.value||saving.value){e.preventDefault();e.returnValue=''}}
async function save(action='save',transition){if(saving.value||loading.value||detailsBusy.value||!doc.value)return;if(action==='save'&&!form.value?.validate())return;if(action!=='save'&&!await confirm.ask(action==='cancel'?'Hủy chứng từ và đảo các bút toán liên quan theo quy tắc ERPNext?':transition?'Thực hiện bước '+erpText(transition)+'?':'Duyệt chứng từ này?'))return;saving.value=true;error.value='';try{const r=await api('action',{doctype:props.doctype,name:isNew.value?undefined:doc.value.name,modified:isNew.value?undefined:doc.value.modified,company:props.company,action,transition,values:action==='save'||action==='submit'?cleanDocument(doc.value):undefined,client_key:key},true);data.value=r;snapshot.value=JSON.stringify(cleanDocument(r.doc));key=crypto.randomUUID();notice.value=action==='cancel'?'Đã hủy chứng từ.':'Đã lưu chứng từ.';version++}catch(e){error.value=e.message}finally{saving.value=false}if(!error.value&&data.value)emit('saved',{doctype:props.doctype,name:data.value.doc.name})}
async function map(target){if(saving.value)return;saving.value=true;error.value='';let result;try{result=await api('map_document',{doctype:props.doctype,name:doc.value.name,target,company:props.company},true)}catch(e){error.value=e.message}finally{saving.value=false}if(result)emit('mapped',result)}
async function reload(){if((dirty.value||detailsBusy.value)&&!await confirm.ask('Bỏ thay đổi chưa lưu và tải lại chứng từ?'))return;load()}
async function amend(){if(!await confirm.ask('Tạo bản sửa đổi từ chứng từ đã hủy?'))return;try{emit('mapped',await api('amend',{doctype:props.doctype,name:doc.value.name,modified:doc.value.modified,company:props.company},true))}catch(e){error.value=e.message}}
function changed(){editRevision++;notice.value='';clearTimeout(previewTimer);if(['Purchase Order','Purchase Receipt','Purchase Invoice','Supplier Quotation','Sales Order','Delivery Note','Sales Invoice','Quotation'].includes(props.doctype)&&doc.value?.company&&doc.value.items?.some(r=>r.item_code))previewTimer=setTimeout(preview,600)}
async function preview(){if(saving.value||detailsBusy.value||!doc.value)return;const id=version,revision=editRevision;detailsBusy.value++;try{const r=await api('preview',{doctype:props.doctype,values:cleanDocument(doc.value),company:props.company||doc.value.company},true);if(id!==version||revision!==editRevision)return;const known=new Set(schema.value.fields.filter(f=>f.read_only||['taxes','items','payment_schedule'].includes(f.fieldname)).map(f=>f.fieldname));for(const f of known)if(r[f]!=null){if(Array.isArray(r[f])&&Array.isArray(doc.value[f]))doc.value[f]=r[f].map((row,i)=>({...doc.value[f][i],...row}));else doc.value[f]=r[f]}}catch(e){if(id===version)error.value=e.message}finally{detailsBusy.value--;if(id===version&&revision!==editRevision){clearTimeout(previewTimer);previewTimer=setTimeout(preview,300)}}}
function quickCreate(context){emit('quick-create',{doctype:context.doctype,onSaved:async value=>{context.row[context.field.fieldname]=value.name;changed();await select({...context,option:{value:value.name}})}})}
async function select({field,row,childtype,option}){if(!option?.value)return;const id=version,token=(rowVersions.get(row)||0)+1;rowVersions.set(row,token);detailsBusy.value++;error.value='';try{let values={};if(['item_code','uom'].includes(field.fieldname)&&childtype&&row.item_code&&['Purchase Order','Purchase Receipt','Purchase Invoice','Supplier Quotation','Sales Order','Delivery Note','Sales Invoice','Quotation','Material Request','Stock Entry','Stock Reconciliation'].includes(props.doctype))values=await api('item_details',{doctype:props.doctype,item_code:field.fieldname==='item_code'?option.value:row.item_code,company:props.company||doc.value.company,row:cleanDocument(row),header:cleanDocument(doc.value)},true);else if(['supplier','customer'].includes(field.fieldname)&&doc.value.company)values=await api('party_details',{doctype:props.doctype,party_type:field.fieldname==='supplier'?'Supplier':'Customer',party:option.value,company:doc.value.company,posting_date:doc.value.posting_date||doc.value.transaction_date,currency:doc.value.currency});else values=await api('linked_values',{doctype:props.doctype,fieldname:field.fieldname,value:option.value,childtype});if(id===version&&rowVersions.get(row)===token){Object.assign(row,values);if(props.doctype==='Stock Entry'&&field.fieldname==='stock_entry_type'&&props.warehouse){if(values.purpose==='Material Receipt')doc.value.to_warehouse=props.warehouse;else doc.value.from_warehouse=props.warehouse}changed()}}catch(e){if(id===version)error.value=e.message}finally{detailsBusy.value--}}
function discardChanges(){snapshot.value=JSON.stringify(cleanDocument(doc.value||{}))}
watch(()=>[props.doctype,props.name,props.company,props.initialDocument],load)
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);load()})
onBeforeUnmount(()=>{version++;clearTimeout(previewTimer);window.removeEventListener('beforeunload',beforeUnload)})
defineExpose({hasChanges:()=>dirty.value,discardChanges,isBusy:()=>saving.value})
</script>
<template>
 <section class="erp-document" :aria-busy="loading||saving">
  <div v-if="doc" class="erp-document-actions"><span class="erp-doc-state">{{isNew?'Chưa lưu':schema?.is_submittable?erpStatus(doc):'Đã lưu'}}{{dirty?' · Chưa lưu thay đổi':''}}</span><span class="erp-action-spacer"></span><Button v-if="(isNew?data.permissions.create:data.permissions.write)&&!readonly" :disabled="saving||loading||detailsBusy>0" @click="save()">{{saving?'Đang lưu…':'Lưu'}}</Button><Button v-if="!isNew&&schema?.is_submittable&&doc.docstatus===0&&data.permissions.submit&&!gated&&!data.transitions?.length" :disabled="saving||dirty||detailsBusy>0" @click="save('submit')">Duyệt</Button><Button v-for="step in gated?[]:data.transitions||[]" :key="step.action" :disabled="saving||dirty" @click="save('workflow',step.action)">{{erpText(step.action)}}</Button><DropdownMenu v-if="!isNew&&data.actions?.length"><DropdownMenuTrigger as-child><Button variant="outline" :disabled="saving||dirty">Tạo chứng từ</Button></DropdownMenuTrigger><DropdownMenuContent><DropdownMenuItem v-for="item in data.actions" :key="item.target" @select="map(item.target)">{{erpText(item.label)}}</DropdownMenuItem></DropdownMenuContent></DropdownMenu><Button v-if="!isNew&&doc.docstatus===1&&data.permissions.cancel" variant="outline" :disabled="saving||dirty" @click="save('cancel')">Hủy chứng từ</Button><Button v-if="!isNew&&doc.docstatus===2&&data.permissions.amend" variant="outline" @click="amend">Sửa đổi</Button><Button v-if="!isNew&&data.permissions.print" as="a" variant="outline" :href="printUrl" target="_blank" rel="noopener">In / PDF</Button><Button variant="outline" :disabled="saving" @click="reload">Tải lại</Button></div>
  <p v-if="error" role="alert" class="erp-error">{{error}}</p><p v-if="notice" role="status" class="erp-notice">{{notice}}</p><p v-if="loading" role="status">Đang tải chứng từ…</p><p v-if="detailsBusy" role="status">Đang tính đơn giá, quy đổi và thuế…</p>
  <form v-if="schema&&doc" novalidate @submit.prevent="save()"><fieldset :disabled="loading||saving"><ErpForm ref="form" :schema="formSchema" :model="doc" :doctype="doctype" :company="company||doc.company" :readonly="readonly" @change="changed" @select="select" @quick-create="quickCreate" @open-link="emit('open-document',$event)" @error="error=$event"/></fieldset></form>
  <div v-if="totals.length" class="erp-document-totals"><div v-for="total in totals" :key="total.label"><span>{{total.label}}</span><strong>{{total.value}}</strong></div></div>
  <ErpApproval v-if="doc&&!isNew" :key="doc.name+doc.modified" :doctype="doctype" :name="doc.name" :company="company||doc.company" :disabled="dirty||saving" @loaded="approval=$event" @changed="load" @error="error=$event"/>
  <SigningPanel v-if="doc&&!isNew&&approval&&!approval.gate" :doctype="doctype" :name="doc.name" :company="company||doc.company" @error="error=$event" @notice="notice=$event"/>
  <ErpConnections v-if="doctype==='Supplier'&&doc&&!isNew&&company" :name="doc.name" :company="company" @open-document="emit('open-document',$event)" @open-list="emit('open-list',$event)" @open-report="emit('open-report',$event)"/>
  <WorkspaceConfirm :open="confirmOpen" :title="confirmTitle" :message="confirmMessage" @answer="confirm.finish"/>
 </section>
</template>
